import java.util.concurrent.CompletableFuture;
import java.util.function.Function;
class Batch<T> {
  Function<T,T> identity = value -> value;
  String run() {
    CompletableFuture<String> task = CompletableFuture.supplyAsync(() -> "item");
    CompletableFuture<String> composed = task.thenCompose(value -> CompletableFuture.completedFuture(value));
    CompletableFuture<String> recovered = composed.exceptionally(error -> "fallback");
    CompletableFuture.allOf(recovered).join();
    return recovered.join();
  }
}

